/// Canvas angle of gravity projected onto a plane with normal `n`.
pub fn fall_angle(n: V3) -> f32 {
    let (dx, dy) = (-n[1] * n[0], 1.0 - n[1] * n[1]);
    if dx.abs() + dy.abs() < 1e-5 { std::f32::consts::FRAC_PI_2 } else { dy.atan2(dx) }
}

