//! "Winter Twilight with Megalith and Spruces" (R11 Winter Flash):
//! An original painting in the manner of Caspar David Friedrich.
//!
//! Sourced historical and artistic vocabulary:
//! - An ancient megalithic stone tomb (Hünengrab / dolmen) in a snowbound landscape,
//!   echoing Friedrich's "Hünengrab im Schnee" (1807) and "Walk at Dusk" (c. 1830).
//! - The dialogue between the ancient gnarled, stag-headed bare oak (bodily death,
//!   fallen antiquity) and resilient evergreen spruces (steadfast faith, eternal life).
//! - Double-layer ground: warm ochre underlayer, cool lead-white brushed top layer.
//! - Twilight sky stippled in thin layers: cool slate-blue and mauve zenith fading into
//!   a luminous winter afterglow along the low horizon [NG p.56; CATS p.127].
//! - Snow modulated with wind-drifts, violet-blue ambient hollows, and warm horizon reflection.
//! - Fine upturned frozen grasses piercing the snow crust [NG p.56].
//! - Solitary wanderer (Rückenfigur) contemplating the ancient stones in the fading light.

use paint::color::{Mix, mix};
use paint::form::Light;
use paint::{
    Apply, Canvas, Fbm, Form, Gesture, Ground, Habit, Held, Mask,
    Orient, Paint, Palette, Rgb, Rng, Sdf, Skeleton, Stipple, Style, Tool,
    gradient, hex, lerp, smoothstep,
};
use paintings::run::{Finish, Run};

const ASPECT: f32 = 1.40;
/// Horizon line in canvas units (y down).
const HORIZON: f32 = 414.0;

fn main() {
    let o = Run::new("r11_winter_flash");
    let mut rng = Rng::new(o.seed);

    // Friedrich's light winter ground: warm lower earth layer leveled with knife,
    // cool lead-white and chalk upper layer brushed [NG p.55; KÖR p.284].
    let st = Style {
        name: "Friedrich Winter",
        width_mm: 450.0,
        ground: vec![
            Ground {
                color: hex("#b89b78"),
                hiding: 0.85,
                um: 90.0,
                stiff: 0.3,
                apply: Apply::Knife { texture: 0.3 },
            },
            Ground {
                color: hex("#dcd6c8"),
                hiding: 0.85,
                um: 60.0,
                stiff: 0.4,
                apply: Apply::Brush,
            },
        ],
        palette: Palette::friedrich_early(),
        relief: (0.06, 0.006),
        ..Style::friedrich()
    };
    let pal = &st.palette;
    let mut c = o.canvas(|| st.prepare(o.width, ASPECT, o.seed));
    let f = c.frame();
    let (_w, h) = (c.width(), c.height());

    // ---------------------------------------------------------------- geometry
    // Far mountain ridge (Riesengebirge profile)
    let ridge_n = Fbm::new(o.seed as u32 + 11, 4, 160.0);
    let ridge = f.per_column(|x| {
        HORIZON - 26.0 + 12.0 * ridge_n.get(x, 0.0)
            - 16.0 * (-((x - 720.0) / 180.0).powi(2)).exp()
            + 8.0 * (-((x - 300.0) / 140.0).powi(2)).exp()
    });

    // Snow boundary against the ridge
    let snow_top = f.per_column(|_x| HORIZON + 2.0);

    // Foreground knoll boundary (separating midground snow from foreground mound)
    let knoll_n = Fbm::new(o.seed as u32 + 15, 3, 110.0);
    let knoll_edge = f.per_column(|x| {
        510.0 - 25.0 * (-((x - 360.0) / 190.0).powi(2)).exp()
              + 18.0 * smoothstep(550.0, 950.0, x)
              + 7.0 * knoll_n.get(x, 2.0)
    });

    // Masks for major spatial zones
    let sky_m = Mask::from_fn(f, |x, y| 1.0 - smoothstep(ridge(x) - 0.5, ridge(x) + 1.5, y));
    let ridge_m = Mask::from_fn(f, |x, y| {
        smoothstep(ridge(x) - 1.0, ridge(x) + 1.0, y)
            * (1.0 - smoothstep(snow_top(x) + 2.0, snow_top(x) + 5.0, y))
    });
    let mid_snow_m = Mask::from_fn(f, |x, y| {
        smoothstep(snow_top(x) - 1.0, snow_top(x) + 1.5, y)
            * (1.0 - smoothstep(knoll_edge(x) - 1.0, knoll_edge(x) + 2.0, y))
    });
    let fg_knoll_m = Mask::from_fn(f, |x, y| smoothstep(knoll_edge(x) - 1.5, knoll_edge(x) + 1.5, y));

    // Sky color function: cool slate-blue zenith -> mauve -> pale ochre afterglow
    let sky_stops: [(f32, Rgb); 6] = [
        (0.00, hex("#47596f")), // slate blue
        (0.22, hex("#6a7788")), // atmospheric blue-gray
        (0.45, hex("#99939e")), // pale mauve
        (0.70, hex("#c4b7a4")), // warm transition
        (0.88, hex("#e2cfab")), // luminous evening glow
        (1.00, hex("#ebd9b5")), // horizon amber-rose
    ];
    let sky_drift = Fbm::new(o.seed as u32 + 21, 3, 350.0);
    let sky_color = move |x: f32, y: f32| -> Rgb {
        let t = (y / HORIZON + 0.02 * sky_drift.get(x * 0.4, y)).clamp(0.0, 1.0);
        gradient(&sky_stops, t, Mix::Light)
    };

    // ------------------------------------------------------------- stage: ground
    if o.stage("ground", &mut c, &mut rng) {
        // Friedrich's thin warm underpainting: establishes values and spatial masses [CATS p.127]
        let whole = Mask::from_fn(f, |_, _| 1.0);
        let under_val = move |x: f32, y: f32| {
            0.15 + 1.8 * smoothstep(HORIZON - 10.0, h, y)
                 + 0.8 * (-((x - 360.0) / 200.0).powi(2) - ((y - 540.0) / 120.0).powi(2)).exp()
        };
        let under_glaze = st.glaze(0.85)
            .color(|_, _| hex("#564230"))
            .angle(|_, _| 0.0)
            .load_at(under_val);
        c.work(&whole, &under_glaze, o.seed * 37 + 1);
        if let Some(b) = st.blend() {
            c.work(&whole, &b, o.seed * 37 + 2);
        }
        c.dry();
    }

    // ------------------------------------------------------------- stage: sky lay
    if o.stage("sky lay", &mut c, &mut rng) {
        // Broad thin lay-in, horizontal strokes
        let lay = st.broad()
            .color(move |x, y| mix(sky_color(x, y), hex("#75757d"), 0.05, Mix::Light))
            .angle(|_, _| 0.0)
            .coverage(4.2)
            .medium(0.35);
        c.work(&sky_m, &lay, o.seed * 43 + 1);

        if let Some(b) = st.blend() {
            c.work(&sky_m, &b.angle(|_, _| 0.0), o.seed * 43 + 2);
        }

        // Wet-into-wet stippling: breaks strokes and fuses layers into Friedrich's fine vibration
        let s1 = Stipple::new(Tool::stippler(2.8))
            .mixed(pal, 0.45)
            .color(sky_color)
            .coverage(|_, _| 2.2)
            .pressure(0.5, 0.85)
            .dips(22, 0.4, 0.5);
        c.stipple(&sky_m, &s1, o.seed * 43 + 3);
        c.dry();
    }

    // ------------------------------------------------------------- stage: sky glow
    if o.stage("sky glow", &mut c, &mut rng) {
        // Dry stipple pass: finer and lighter, intensifying the warm afterglow
        let glow_color = move |x: f32, y: f32| {
            mix(sky_color(x, y), hex("#f0deb8"), 0.08 + 0.25 * smoothstep(180.0, HORIZON, y), Mix::Light)
        };
        let s2 = Stipple::new(Tool::stippler(1.5))
            .mixed(pal, 0.52)
            .color(glow_color)
            .coverage(|_, y| 2.4 * smoothstep(140.0, HORIZON - 10.0, y))
            .pressure(0.45, 0.8)
            .dips(26, 0.35, 0.6);
        c.stipple(&sky_m, &s2, o.seed * 47 + 1);
        c.dry();
    }

    // ------------------------------------------------------------- stage: far hills
    if o.stage("far hills", &mut c, &mut rng) {
        // Distant mountain ridge in cold atmospheric blue-gray
        let ridge_col = |_, y: f32| {
            let t = ((y - (HORIZON - 35.0)) / 40.0).clamp(0.0, 1.0);
            gradient(
                &[(0.0, hex("#5f6777")), (0.5, hex("#565d6c")), (1.0, hex("#474d5b"))],
                t,
                Mix::Light,
            )
        };
        let ridge_handling = st.body()
            .color(ridge_col)
            .angle(|_, _| 0.05)
            .angle_jitter(0.1)
            .length(25.0, 60.0)
            .coverage(4.0)
            .medium(0.25);
        c.work(&ridge_m, &ridge_handling, o.seed * 53 + 1);

        // Valley mist stippled across the foot of the mountains
        let mist_n = Fbm::new(o.seed as u32 + 57, 4, 180.0);
        let mist_cov = move |x: f32, y: f32| {
            let base = smoothstep(HORIZON - 22.0, HORIZON + 8.0, y);
            let banks = 0.3 * mist_n.get(x * 0.8, y * 2.0);
            (base + banks).clamp(0.0, 1.0) * 2.8
        };
        let mist = Stipple::new(Tool::stippler(2.2))
            .mixed(pal, 0.65)
            .color(|_, _| hex("#cfcad0"))
            .coverage(mist_cov)
            .pressure(0.4, 0.8)
            .dips(18, 0.3, 0.6)
            .aim(false);
        c.stipple(&ridge_m, &mist, o.seed * 53 + 2);
        c.dry();
    }

    // ------------------------------------------------------------- stage: midground
    if o.stage("midground", &mut c, &mut rng) {
        // Midground snowfield: rolling snow slopes with wind drifts and icy tarn
        let drift = Fbm::new(o.seed as u32 + 61, 4, 130.0);
        let mid_snow_color = move |x: f32, y: f32| -> Rgb {
            let d = ((y - HORIZON) / (520.0 - HORIZON)).clamp(0.0, 1.0);
            // Frozen tarn area: elliptical depression on the right
            let tarn_dx = (x - 720.0) / 130.0;
            let tarn_dy = (y - 470.0) / 32.0;
            let in_tarn = (1.0 - (tarn_dx * tarn_dx + tarn_dy * tarn_dy)).clamp(0.0, 1.0);

            let base_snow = gradient(
                &[
                    (0.0, hex("#d8d2c6")), // horizon warmth
                    (0.3, hex("#c8c7c9")),
                    (0.7, hex("#b5b6c2")),
                    (1.0, hex("#a0a3b2")), // cool blue foreground
                ],
                d,
                Mix::Light,
            );
            // Wind drift lighting: subtle slope variations
            let slope = drift.get(x * 0.25, y * 2.0);
            let snow = if slope >= 0.0 {
                mix(base_snow, hex("#ded8c7"), 0.45 * slope, Mix::Light)
            } else {
                mix(base_snow, hex("#8d8fa3"), 0.5 * -slope, Mix::Light)
            };

            // If inside tarn, blend in icy reflection
            if in_tarn > 0.0 {
                let ice_col = mix(hex("#626a76"), hex("#b6b3af"), 0.5, Mix::Light);
                mix(snow, ice_col, in_tarn.powf(0.8) * 0.85, Mix::Light)
            } else {
                snow
            }
        };

        let snow_handling = st.body()
            .color(mid_snow_color)
            .angle(|x, _| 0.03 + 0.02 * (x / 200.0).sin())
            .angle_jitter(0.12)
            .length(30.0, 75.0)
            .coverage(4.6)
            .medium(0.26);
        c.work(&mid_snow_m, &snow_handling, o.seed * 67 + 1);

        // Distant Gothic ruined chapel on the low hill to the left
        paint_ruin(&mut c, pal, 232.0, 412.0, 24.0, o.seed * 71 + 3);
        c.dry();
    }

    // ------------------------------------------------------------- stage: spruces
    if o.stage("spruces", &mut c, &mut rng) {
        // Grove of evergreen Norway spruces standing by the frozen tarn
        let spruce_specs = [
            (625.0, 485.0, 110.0),
            (660.0, 478.0, 140.0),
            (695.0, 468.0, 125.0),
            (735.0, 460.0, 155.0),
            (775.0, 462.0, 130.0),
            (810.0, 472.0, 105.0),
            (845.0, 488.0, 85.0),
        ];

        for (i, &(sx, sy, sh)) in spruce_specs.iter().enumerate() {
            let s_seed = o.seed * 109 + (i as u64) * 17;
            paint_spruce(&mut c, pal, (sx, sy), sh, s_seed);
        }
        c.dry();
    }

    // Form setup for dolmen and rocks (done between stages, seeded deterministically)
    let upright1 = Sdf::block([315.0, 528.0, 15.0], [36.0, 68.0, 40.0], 7.0)
        .rough(2.5, 20.0, (o.seed + 201) as u32, true);
    let upright2 = Sdf::block([405.0, 538.0, -10.0], [40.0, 74.0, 44.0], 8.0)
        .rough(2.8, 22.0, (o.seed + 202) as u32, true);
    let upright3 = Sdf::block([355.0, 512.0, -35.0], [34.0, 60.0, 36.0], 6.0)
        .rough(2.2, 18.0, (o.seed + 203) as u32, true);
    let capstone = Sdf::block([358.0, 475.0, 0.0], [135.0, 34.0, 85.0], 8.0)
        .rough(3.0, 25.0, (o.seed + 204) as u32, true)
        .turn([358.0, 475.0, 0.0], 0.06, -0.05, 0.03);

    let boulder1 = Sdf::ellipsoid([235.0, 605.0, 20.0], [32.0, 22.0, 26.0])
        .rough(2.5, 15.0, (o.seed + 205) as u32, true);
    let boulder2 = Sdf::block([465.0, 598.0, 10.0], [46.0, 32.0, 36.0], 8.0)
        .rough(2.2, 16.0, (o.seed + 206) as u32, true);
    let boulder3 = Sdf::ellipsoid([535.0, 622.0, 5.0], [28.0, 18.0, 22.0])
        .rough(2.0, 14.0, (o.seed + 207) as u32, true);

    let mut stone_form = Form::new(f);
    stone_form.add(&upright1, 46.0);
    stone_form.add(&upright2, 49.0);
    stone_form.add(&upright3, 53.0);
    stone_form.add(&capstone, 47.0);
    stone_form.add(&boulder1, 41.0);
    stone_form.add(&boulder2, 43.0);
    stone_form.add(&boulder3, 44.0);

    let stone_light = Light::new((-0.2, -0.3), -0.4)
        .ambient(0.24)
        .bounce(0.36, [-0.1, 0.8, 0.3])
        .penumbra(0.08);
    stone_form.light(stone_light);
    let stones_m = stone_form.mask();

    // ------------------------------------------------------------- stage: dolmen & rocks
    if o.stage("dolmen & rocks", &mut c, &mut rng) {
        let stone_color = |x: f32, y: f32| -> Rgb {
            if let Some(s) = stone_form.sample(x, y) {
                let sh = &s.shade;
                let core = hex("#1f1c21");
                let shadow = hex("#41404c");
                let bounce = hex("#695d4f");
                let half = hex("#766e63");
                let lit = hex("#a49784");

                let dark = mix(core, shadow, sh.sky, Mix::Pigment);
                let dark = mix(dark, bounce, (sh.bounce * 0.9).min(0.55), Mix::Pigment);
                let light = mix(half, lit, sh.direct.powf(0.8), Mix::Pigment);
                mix(dark, light, sh.lit(0.12), Mix::Pigment)
            } else {
                hex("#323038")
            }
        };

        let fall_angle = |x: f32, y: f32| stone_form.sample(x, y).map_or(0.0, |s| s.fall());
        let stone_handling = st.body()
            .color(stone_color)
            .angle(fall_angle)
            .angle_jitter(0.12)
            .length(14.0, 32.0)
            .coverage(4.8)
            .medium(0.22);
        c.work(&stones_m, &stone_handling, o.seed * 83 + 1);

        // Plane breaks and crevices
        let breaks_m = stone_form.breaks(1.2, 0.45, 1.8);
        let dark_crevice = pal.paint(hex("#161418"), 0.15).with_hiding(0.98);
        let lit_edge = pal.paint(hex("#b8ac9a"), 0.2).with_hiding(0.85);

        // Highlight arrises and deepen joints
        for _ in 0..60 {
            let rx = rng.range(220.0, 560.0);
            let ry = rng.range(440.0, 640.0);
            if breaks_m.get(rx, ry) > 0.4 {
                let b = stone_form.bend(rx, ry, 2.0);
                if b > 0.25 {
                    // Convex arris: catch light
                    let mut a_held = Held::new(Tool::rigger(0.45), rng.next_u64());
                    a_held.load(lit_edge, 0.7);
                    c.touch(&mut a_held, (rx, ry), 0.7, None);
                } else if b < -0.25 {
                    // Concave joint: deep shadow
                    let mut j_held = Held::new(Tool::rigger(0.45), rng.next_u64());
                    j_held.load(dark_crevice, 0.8);
                    c.touch(&mut j_held, (rx, ry), 0.8, None);
                }
            }
        }
        c.dry();
    }

    // Grow the ancient dead oak skeleton deterministically
    let oak_sk = Habit {
        years: 52,
        vigor: 1.16,
        abort: 0.38,
        decay: 0.44,
        breakage: 0.18,
        trunk: 0.054,
        ..Habit::dead_oak()
    }.grow((180.0, 642.0), 515.0, o.seed + 301);

    // ------------------------------------------------------------- stage: ancient oak
    if o.stage("ancient oak", &mut c, &mut rng) {
        paint_oak(&mut c, pal, &oak_sk, o.seed * 97 + 1);
        c.dry();
    }

    // ------------------------------------------------------------- stage: foreground snow
    if o.stage("foreground snow", &mut c, &mut rng) {
        // Sculpted snowdrifts over the foreground knoll wrapping around stones
        let fg_drift = Fbm::new(o.seed as u32 + 131, 4, 90.0);
        let fg_snow_color = move |x: f32, y: f32| -> Rgb {
            let t = ((y - 500.0) / (h - 500.0)).clamp(0.0, 1.0);
            let base_snow = gradient(
                &[
                    (0.0, hex("#dcd5c7")),
                    (0.4, hex("#c5c5cb")),
                    (0.8, hex("#a6a8b8")),
                    (1.0, hex("#9497a8")), // cool foreground snow
                ],
                t,
                Mix::Light,
            );

            // Cast shadow of the dolmen and oak: diagonal from (-0.2, -0.3)
            let in_dolmen_shadow = smoothstep(360.0, 480.0, x) * (1.0 - smoothstep(490.0, 580.0, x))
                * smoothstep(510.0, 560.0, y) * (1.0 - smoothstep(610.0, 660.0, y));

            let in_oak_shadow = smoothstep(190.0, 240.0, x) * (1.0 - smoothstep(340.0, 410.0, x))
                * smoothstep(610.0, 630.0, y) * (1.0 - smoothstep(670.0, 710.0, y));

            let shadow_amt = (in_dolmen_shadow * 0.7 + in_oak_shadow * 0.6).clamp(0.0, 0.85);

            let slope = fg_drift.get(x * 0.28, y * 1.8);
            let lit_snow = if slope >= 0.0 {
                mix(base_snow, hex("#e2dcce"), 0.5 * slope, Mix::Light)
            } else {
                mix(base_snow, hex("#8a8ca3"), 0.55 * -slope, Mix::Light)
            };

            // In shadow, snow reflects cold blue-violet sky
            mix(lit_snow, hex("#7d8299"), shadow_amt, Mix::Light)
        };

        // Foreground snow covers the knoll except where the stones protrude
        let snow_over_knoll = fg_knoll_m.clone().sub(&stones_m);
        let fg_handling = st.body()
            .color(fg_snow_color)
            .angle(|x, _| -0.04 + 0.03 * (x / 180.0).cos())
            .angle_jitter(0.12)
            .length(25.0, 65.0)
            .coverage(4.8)
            .medium(0.24);
        c.work(&snow_over_knoll, &fg_handling, o.seed * 137 + 1);

        // Snow caps on the dolmen capstone and boulders!
        let snow_cap_paint = pal.paint(hex("#ede8dd"), 0.15).with_hiding(0.96);
        let snow_shade_paint = pal.paint(hex("#9da2b4"), 0.2).with_hiding(0.9);

        // Capstone snow pillow: thick blanket on the horizontal slab
        let cap_pts = vec![
            (295.0, 465.0),
            (330.0, 458.0),
            (365.0, 456.0),
            (400.0, 459.0),
            (425.0, 467.0),
        ];
        let mut sn_held = Held::new(Tool::round_sable(10.0), rng.next_u64());
        sn_held.load(snow_cap_paint, 1.0);
        c.drag(
            &mut sn_held,
            &Gesture::new(cap_pts.clone())
                .pressure(0.6, 0.9)
                .ramps(0.2, 0.2)
                .orient(Orient::Across),
            None,
        );

        // Soft undercut shadow beneath the snow cap overhang
        let mut sn_sh_held = Held::new(Tool::rigger(0.8), rng.next_u64());
        sn_sh_held.load(snow_shade_paint, 0.7);
        c.drag(
            &mut sn_sh_held,
            &Gesture::new(vec![(298.0, 469.0), (360.0, 462.0), (422.0, 471.0)])
                .pressure(0.5, 0.5)
                .ramps(0.1, 0.1)
                .orient(Orient::Across),
            None,
        );

        // Snow caps on foreground boulders
        for &(bx, by, bw) in &[(235.0, 595.0, 18.0), (465.0, 582.0, 22.0), (535.0, 614.0, 14.0)] {
            let pts = vec![(bx - bw * 0.45, by), (bx, by - 4.0), (bx + bw * 0.45, by + 1.0)];
            let mut b_held = Held::new(Tool::round_sable(bw * 0.35), rng.next_u64());
            b_held.load(snow_cap_paint, 0.85);
            c.drag(&mut b_held, &Gesture::new(pts).pressure(0.5, 0.8).ramps(0.2, 0.2).orient(Orient::Across), None);
        }
        c.dry();
    }

    // ------------------------------------------------------------- stage: details
    if o.stage("details", &mut c, &mut rng) {
        // Solitary Wanderer (Rückenfigur) standing on the snow crest to the right
        paint_wanderer(&mut c, pal, (730.0, 582.0), 66.0, o.seed * 151 + 7);

        // Frozen winter grasses and reeds piercing through the snow
        let grass_clusters = [
            (210.0, 638.0, 18, 16.0), // base of oak
            (255.0, 625.0, 12, 14.0), // near left boulder
            (310.0, 570.0, 16, 15.0), // foot of left upright
            (415.0, 585.0, 20, 17.0), // foot of right upright
            (470.0, 630.0, 14, 13.0), // near center boulder
            (530.0, 635.0, 12, 12.0), // near right boulder
            (630.0, 520.0, 10, 14.0), // tarn bank
            (680.0, 595.0, 15, 15.0), // path near wanderer
        ];
        paint_grasses(&mut c, pal, &grass_clusters, o.seed * 163 + 11);
        c.dry();
    }

    o.finish(&mut c, &mut rng, &Finish::aged(st.relief));
}

