/// Ruined gothic chapel gable and lancet arch on the distant hill.
fn paint_ruin(c: &mut Canvas, pal: &Palette, x0: f32, y_base: f32, h_ruin: f32, seed: u64) {
    let mut rng = Rng::new(seed);
    let stone = pal.paint(hex("#434652"), 0.2).with_hiding(0.95);
    let dark_crevice = pal.paint(hex("#272932"), 0.15).with_hiding(0.98);
    let snow = pal.paint(hex("#dad5cb"), 0.15).with_hiding(0.9);

    // Left wall pillar
    let mut left_held = Held::new(Tool::rigger(2.4), rng.next_u64());
    left_held.load(stone, 0.95);
    c.drag(
        &mut left_held,
        &Gesture::new(vec![(x0, y_base), (x0, y_base - h_ruin * 0.85)])
            .pressure(0.9, 0.7)
            .ramps(0.0, 0.1)
            .orient(Orient::Along),
        None,
    );

    // Right wall pillar & buttress
    let mut right_held = Held::new(Tool::rigger(2.8), rng.next_u64());
    right_held.load(stone, 0.95);
    c.drag(
        &mut right_held,
        &Gesture::new(vec![(x0 + 18.0, y_base), (x0 + 17.0, y_base - h_ruin * 0.95)])
            .pressure(0.9, 0.6)
            .ramps(0.0, 0.1)
            .orient(Orient::Along),
        None,
    );

    // Pointed gothic arch bridging across
    let arch_pts_l = vec![(x0 + 1.0, y_base - h_ruin * 0.6), (x0 + 8.5, y_base - h_ruin * 0.85)];
    let arch_pts_r = vec![(x0 + 16.0, y_base - h_ruin * 0.6), (x0 + 8.5, y_base - h_ruin * 0.85)];
    let mut arch_held = Held::new(Tool::rigger(1.4), rng.next_u64());
    arch_held.load(dark_crevice, 0.9);
    c.drag(&mut arch_held, &Gesture::new(arch_pts_l).pressure(0.7, 0.4).orient(Orient::Across), None);
    c.drag(&mut arch_held, &Gesture::new(arch_pts_r).pressure(0.7, 0.4).orient(Orient::Across), None);

    // Snow touches on ruined wall tops
    let mut sn_held = Held::new(Tool::rigger(0.8), rng.next_u64());
    sn_held.load(snow, 0.8);
    c.drag(&mut sn_held, &Gesture::new(vec![(x0 - 1.5, y_base - h_ruin * 0.86), (x0 + 1.5, y_base - h_ruin * 0.86)]).pressure(0.6, 0.6).orient(Orient::Across), None);
    c.drag(&mut sn_held, &Gesture::new(vec![(x0 + 15.5, y_base - h_ruin * 0.96), (x0 + 18.5, y_base - h_ruin * 0.96)]).pressure(0.6, 0.6).orient(Orient::Across), None);
}

/// Norway spruce (*Picea abies*) painted with 3D whorl boughs, drooping needle fringes, and snow.
fn paint_spruce(
    c: &mut Canvas,
    pal: &Palette,
    at: (f32, f32),
    height: f32,
    seed: u64,
) {
    let mut rng = Rng::new(seed);
    let dark_needles = pal.paint(hex("#141b16"), 0.1).with_hiding(0.97);
    let mid_needles = pal.paint(hex("#1f2921"), 0.15).with_hiding(0.95);
    let trunk_paint = pal.paint(hex("#1a1613"), 0.1).with_hiding(0.98);
    let snow_paint = pal.paint(hex("#e5e2d8"), 0.12).with_hiding(0.9);

    let (x0, y0) = at;
    let apex_y = y0 - height;
    let apex_x = x0 + rng.range(-1.0, 1.0);

    // 1. Central trunk
    let trunk_w = (height * 0.034).clamp(0.8, 3.4);
    let mut tr_held = Held::new(Tool::round_sable(trunk_w), rng.next_u64());
    tr_held.load(trunk_paint, 1.0);
    c.drag(
        &mut tr_held,
        &Gesture::new(vec![(x0, y0), (apex_x, apex_y)])
            .pressure(1.0, 0.1)
            .ramps(0.0, 0.4)
            .orient(Orient::Along),
        None,
    );

    // 2. Whorls of boughs (3D projected)
    let tiers = (height / 6.0).clamp(9.0, 24.0) as usize;
    for tier in 0..tiers {
        let t = (tier as f32 + 0.5) / tiers as f32; // 0 apex, 1 base
        let by = apex_y + t * height;
        let max_reach = height * 0.22 * (0.18 + 0.82 * (t * 1.15).min(1.0)) * (1.0 - 0.15 * t * t);
        let bough_w = (trunk_w * (1.0 - 0.7 * t)).clamp(0.35, 1.6);

        let n_boughs = rng.range(3.0, 5.2) as usize;
        let phi0 = rng.range(0.0, std::f32::consts::TAU);
        for k in 0..n_boughs {
            let phi = phi0 + k as f32 * std::f32::consts::TAU / n_boughs as f32 + rng.range(-0.25, 0.25);
            let cos_p = phi.cos();
            let sin_p = phi.sin();
            if cos_p.abs() < 0.2 { continue; }

            let side = cos_p.signum();
            let b_len = max_reach * (0.4 + 0.6 * cos_p.abs()) * rng.range(0.85, 1.15);
            let sag = 1.5 + 4.5 * t;
            let upturn = 0.8 + 2.0 * (1.0 - t);

            let tip_x = x0 + side * b_len;
            let mid_x = x0 + side * b_len * 0.55;
            let mid_y = by + sag + sin_p * 2.0;
            let tip_y = by + sag - upturn + sin_p * 1.5;

            let pts = vec![(x0, by), (mid_x, mid_y), (tip_x, tip_y)];
            let mut b_held = Held::new(Tool::rigger(bough_w), rng.next_u64());
            b_held.load(trunk_paint, 0.8);
            c.drag(&mut b_held, &Gesture::new(pts).pressure(0.8, 0.2).ramps(0.0, 0.3).orient(Orient::Across), None);

            // Pendant needle fringes
            let hatches = (b_len / 1.6).clamp(3.0, 14.0) as usize;
            for h in 0..hatches {
                let s = (h as f32 + 0.5) / hatches as f32;
                let hx = lerp(x0, tip_x, s);
                let hy = lerp(by, tip_y, s);
                let needle_len = (height * 0.04 * (0.35 + 0.65 * t)).clamp(1.5, 6.0);
                let pts_h = vec![
                    (hx, hy),
                    (hx + side * needle_len * 0.4, hy + needle_len * 0.8),
                    (hx + side * needle_len * 0.6, hy + needle_len),
                ];
                let col = if (h + tier) % 2 == 0 { dark_needles } else { mid_needles };
                let mut n_held = Held::new(Tool::rigger(0.35), rng.next_u64());
                n_held.load(col, 0.7);
                c.drag(&mut n_held, &Gesture::new(pts_h).pressure(0.7, 0.1).ramps(0.0, 0.4).orient(Orient::Across), None);
            }

            // Snow dusting on boughs
            if t > 0.12 && t < 0.88 && rng.chance(0.68) {
                let snow_pts = vec![
                    (x0 + side * b_len * 0.15, by - 0.4),
                    (mid_x, mid_y - 0.6),
                    (x0 + side * b_len * 0.85, tip_y - 0.3),
                ];
                let mut s_held = Held::new(Tool::rigger(0.45), rng.next_u64());
                s_held.load(snow_paint, 0.65);
                c.drag(&mut s_held, &Gesture::new(snow_pts).pressure(0.4, 0.2).ramps(0.2, 0.4).orient(Orient::Across), None);
            }
        }
    }
}

/// The ancient bare oak tree: limb following, tapering sable/rigger, bark, splinters, crotch snow.
fn paint_oak(
    c: &mut Canvas,
    pal: &Palette,
    sk: &Skeleton,
    seed: u64,
) {
    let mut rng = Rng::new(seed);
    let dark_bark = pal.paint(hex("#221d19"), 0.1).with_hiding(0.98);
    let dead_bark = pal.paint(hex("#56504a"), 0.15).with_hiding(0.95);
    let wood_splinter = pal.paint(hex("#9e907a"), 0.2).with_hiding(0.92);
    let lit_streak = pal.paint(hex("#7c7062"), 0.25).with_hiding(0.75);
    let snow_pillow = pal.paint(hex("#eae6dd"), 0.15).with_hiding(0.92);

    // 1. Draw each limb, base to tip
    for l in sk.limbs.iter().filter(|l| !l.is_empty()) {
        let n = l.pts.len();
        if n < 2 { continue; }
        let w_base = l.w[0];
        let w_tip = *l.w.last().unwrap();

        let brush_w = w_base.clamp(0.4, 18.0);
        let tool = if brush_w > 1.8 {
            Tool::round_sable(brush_w * 0.8)
        } else {
            Tool::rigger(brush_w.max(0.35))
        };

        let paint = if l.dead || l.dead_from == 0 { dead_bark } else { dark_bark };
        let mut held = Held::new(tool, rng.next_u64());
        held.load(paint, 0.9);

        let p0 = 1.0;
        let p1 = (w_tip / w_base).clamp(0.1, 1.0);
        let g = Gesture::new(l.pts.clone())
            .pressure(p0, p1)
            .ramps(0.0, if l.broken { 0.0 } else { 0.35 })
            .orient(Orient::Across)
            .shake(0.35);
        c.drag(&mut held, &g, None);

        // Splintered break if limb is broken
        if l.broken {
            let tip = *l.pts.last().unwrap();
            let prev = l.pts[n - 2];
            let dir = (tip.0 - prev.0, tip.1 - prev.1);
            let d_len = (dir.0 * dir.0 + dir.1 * dir.1).sqrt().max(1e-4);
            let u_dir = (dir.0 / d_len, dir.1 / d_len);

            for s in 0..3 {
                let s_len = (w_tip * 1.8 * (0.8 + 0.4 * s as f32)).clamp(1.5, 8.0);
                let lateral = (s as f32 - 1.0) * w_tip * 0.4;
                let s_pts = vec![
                    tip,
                    (tip.0 + u_dir.0 * s_len + lateral, tip.1 + u_dir.1 * s_len),
                ];
                let col = if s == 1 { wood_splinter } else { dead_bark };
                let mut sp_held = Held::new(Tool::rigger(0.4), rng.next_u64());
                sp_held.load(col, 0.8);
                c.drag(
                    &mut sp_held,
                    &Gesture::new(s_pts).pressure(0.8, 0.1).ramps(0.0, 0.4).orient(Orient::Across),
                    None,
                );
            }
        }
    }

    c.dry();

    // 2. Lean dry-brush lit streaks on big limbs facing the twilight glow
    for l in sk.limbs.iter().filter(|l| !l.is_empty() && l.w[0] > 2.5 && !l.root) {
        let n = l.pts.len();
        if n < 3 { continue; }
        let lit_pts: Vec<(f32, f32)> = l.pts.iter().enumerate().map(|(i, &(x, y))| {
            let w = l.w[i];
            (x + w * 0.3, y)
        }).collect();

        let mut lit_held = Held::new(Tool::round_sable(1.2), rng.next_u64());
        lit_held.load(lit_streak, 0.4);
        let g = Gesture::new(lit_pts).pressure(0.5, 0.2).ramps(0.2, 0.3).orient(Orient::Across);
        c.drag(&mut lit_held, &g, None);
    }

    // 3. Snow settled in branch crotches and on horizontal limbs
    for l in sk.limbs.iter().filter(|l| !l.is_empty() && l.w[0] > 1.8 && !l.root) {
        let n = l.pts.len();
        for i in 1..n - 1 {
            let (p0, p1, p2) = (l.pts[i - 1], l.pts[i], l.pts[i + 1]);
            let dx = p2.0 - p0.0;
            let dy = p2.1 - p0.1;
            if dx.abs() > dy.abs() * 0.8 && rng.chance(0.65) {
                let w = l.w[i];
                let snow_pts = vec![
                    (p1.0 - dx * 0.3, p1.1 - w * 0.45),
                    (p1.0, p1.1 - w * 0.55),
                    (p1.0 + dx * 0.3, p1.1 - w * 0.45),
                ];
                let mut sn_held = Held::new(Tool::round_sable((w * 0.4).clamp(0.5, 2.5)), rng.next_u64());
                sn_held.load(snow_pillow, 0.7);
                c.drag(
                    &mut sn_held,
                    &Gesture::new(snow_pts).pressure(0.4, 0.6).ramps(0.2, 0.2).orient(Orient::Across),
                    None,
                );
            }
        }
    }
}

/// The solitary wanderer (Rückenfigur) in traditional German traveler's dress with walking staff.
fn paint_wanderer(
    c: &mut Canvas,
    pal: &Palette,
    at: (f32, f32),
    height: f32,
    seed: u64,
) {
    let mut rng = Rng::new(seed);
    let cape_body = pal.paint(hex("#242723"), 0.1).with_hiding(0.98);
    let dark_boot = pal.paint(hex("#151312"), 0.1).with_hiding(0.98);
    let hat_paint = pal.paint(hex("#171615"), 0.1).with_hiding(0.98);
    let staff_paint = pal.paint(hex("#423525"), 0.15).with_hiding(0.95);
    let rim_light = pal.paint(hex("#9e9786"), 0.25).with_hiding(0.7);
    let shadow_snow = pal.paint(hex("#7d8498"), 0.4).with_hiding(0.45);

    let (x0, y0) = at;

    // 1. Cast shadow on snow (trailing toward the right-forward)
    let sh_pts = vec![
        (x0, y0),
        (x0 + height * 0.35, y0 + height * 0.12),
        (x0 + height * 0.7, y0 + height * 0.22),
    ];
    let mut sh_held = Held::new(Tool::round_sable(height * 0.12), rng.next_u64());
    sh_held.load(shadow_snow, 0.6);
    c.drag(
        &mut sh_held,
        &Gesture::new(sh_pts).pressure(0.8, 0.2).ramps(0.1, 0.4).orient(Orient::Across),
        None,
    );

    // 2. Boots and legs
    let leg_w = (height * 0.06).clamp(0.6, 3.0);
    for dx in [-height * 0.04, height * 0.03] {
        let leg_pts = vec![
            (x0 + dx, y0 - height * 0.35),
            (x0 + dx, y0 - height * 0.1),
            (x0 + dx - height * 0.02, y0),
        ];
        let mut l_held = Held::new(Tool::round_sable(leg_w), rng.next_u64());
        l_held.load(dark_boot, 0.9);
        c.drag(&mut l_held, &Gesture::new(leg_pts).pressure(0.9, 0.8).orient(Orient::Along), None);
    }

    // 3. Walking staff (planted to the left)
    let staff_pts = vec![
        (x0 - height * 0.16, y0 - height * 0.72),
        (x0 - height * 0.18, y0 - height * 0.35),
        (x0 - height * 0.20, y0 + height * 0.02),
    ];
    let mut st_held = Held::new(Tool::rigger(0.45), rng.next_u64());
    st_held.load(staff_paint, 0.9);
    c.drag(&mut st_held, &Gesture::new(staff_pts).pressure(0.8, 0.7).orient(Orient::Along), None);

    // 4. Heavy traveler's cape
    let cape_pts = vec![
        (x0, y0 - height * 0.82),
        (x0 - height * 0.08, y0 - height * 0.55),
        (x0 - height * 0.12, y0 - height * 0.28),
    ];
    let mut c_held = Held::new(Tool::round_sable(height * 0.18), rng.next_u64());
    c_held.load(cape_body, 1.0);
    c.drag(&mut c_held, &Gesture::new(cape_pts).pressure(0.5, 1.0).ramps(0.1, 0.1).orient(Orient::Across), None);

    let cape_pts2 = vec![
        (x0, y0 - height * 0.82),
        (x0 + height * 0.07, y0 - height * 0.55),
        (x0 + height * 0.10, y0 - height * 0.28),
    ];
    let mut c_held2 = Held::new(Tool::round_sable(height * 0.18), rng.next_u64());
    c_held2.load(cape_body, 1.0);
    c.drag(&mut c_held2, &Gesture::new(cape_pts2).pressure(0.5, 1.0).ramps(0.1, 0.1).orient(Orient::Across), None);

    // 5. Head and beret
    let mut hd_held = Held::new(Tool::round_sable(height * 0.1), rng.next_u64());
    hd_held.load(dark_boot, 0.8);
    c.touch(&mut hd_held, &Touch::at(x0, y0 - height * 0.88).pressure(0.8), None);

    let hat_pts = vec![
        (x0 - height * 0.10, y0 - height * 0.92),
        (x0, y0 - height * 0.94),
        (x0 + height * 0.08, y0 - height * 0.93),
    ];
    let mut hat_held = Held::new(Tool::round_sable(height * 0.08), rng.next_u64());
    hat_held.load(hat_paint, 0.95);
    c.drag(&mut hat_held, &Gesture::new(hat_pts).pressure(0.9, 0.7).orient(Orient::Across), None);

    // 6. Twilight rim light
    let rim_pts = vec![
        (x0 - height * 0.09, y0 - height * 0.93),
        (x0 - height * 0.07, y0 - height * 0.82),
        (x0 - height * 0.11, y0 - height * 0.55),
    ];
    let mut rim_held = Held::new(Tool::rigger(0.35), rng.next_u64());
    rim_held.load(rim_light, 0.5);
    c.drag(&mut rim_held, &Gesture::new(rim_pts).pressure(0.4, 0.3).ramps(0.1, 0.2).orient(Orient::Across), None);
}

/// Frozen grasses and reeds piercing the snow (Friedrich's fine upturning strokes [NG p.56]).
fn paint_grasses(
    c: &mut Canvas,
    pal: &Palette,
    clusters: &[(f32, f32, usize, f32)],
    seed: u64,
) {
    let mut rng = Rng::new(seed);
    let umber = pal.paint(hex("#4e3b26"), 0.15).with_hiding(0.95);
    let ochre = pal.paint(hex("#7b643a"), 0.18).with_hiding(0.92);
    let dark = pal.paint(hex("#2a2016"), 0.15).with_hiding(0.96);

    for &(cx, cy, count, h) in clusters {
        for _ in 0..count {
            let x = cx + rng.range(-15.0, 15.0);
            let y = cy + rng.range(-4.0, 6.0);
            let gh = h * rng.range(0.7, 1.3);
            let lean = rng.range(-0.4, 0.4);
            let curve = rng.range(-0.3, 0.3);

            let tip_x = x + gh * (lean + curve);
            let mid_x = x + gh * lean * 0.4;
            let tip_y = y - gh;
            let mid_y = y - gh * 0.55;

            let pts = vec![(x, y), (mid_x, mid_y), (tip_x, tip_y)];
            let col = if rng.chance(0.5) { umber } else if rng.chance(0.6) { ochre } else { dark };
            let mut g_held = Held::new(Tool::rigger(0.35), rng.next_u64());
            g_held.load(col, 0.7);
            c.drag(
                &mut g_held,
                &Gesture::new(pts)
                    .pressure(0.8, 0.1)
                    .ramps(0.0, 0.4)
                    .orient(Orient::Across),
                None,
            );
        }
    }
}

