    let mut c_held = Held::new(Tool::rigger(0.8), rng.next_u64());
    c_held.load(snow_crest_paint, 0.8);
    c.drag(&mut c_held, &Gesture::new(cr_pts).pressure(0.5, 0.4).ramps(0.1, 0.1).orient(Orient::Across), None);
}

